from datetime import datetime, timedelta, timezone
import sqlite3
import unittest
from unittest.mock import patch

import config
import uniclubs_database


NOW = datetime(2026, 11, 15, 17, 0, tzinfo=timezone.utc)
SEEN_TIME = '2026-11-15T17:00:00.000000Z'
CLUB_URL = 'https://uniclubs.ch/hsg/clubs/example-club'
EVENT_URL = 'https://uniclubs.ch/hsg/clubs/example-club/events/example-event'


def event_record(club_id, **changes):
    """Return a valid public catalogue record with explicit test overrides."""
    # Course: U03 s2 – keyword arguments keep each boundary case easy to read.
    record = {
        'external_id': 'event-1',
        'club_id': club_id,
        'title': 'Example workshop',
        'start_utc': '2026-11-16T11:00:00Z',
        'end_utc': '2026-11-16T12:00:00Z',
        'source_url': EVENT_URL,
    }
    record.update(changes)
    return record


class UniClubsDatabaseTests(unittest.TestCase):
    """Verify the new catalogue independently of the existing WeekWise database."""

    def setUp(self):
        """Create an empty catalogue without touching files or the network."""
        self.connection = uniclubs_database.get_connection(':memory:')
        self.addCleanup(self.connection.close)
        uniclubs_database.init_db(self.connection)

    def add_club(self):
        """Insert one fictional club and return its local integer identifier."""
        return uniclubs_database.add_club(
            self.connection, 'club-1', 'Example Club', CLUB_URL)

    def test_schema_is_separate_empty_and_enforces_foreign_keys(self):
        """Create just the three catalogue tables and enable references on the connection."""
        rows = self.connection.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'"
        ).fetchall()
        self.assertEqual({row['name'] for row in rows}, {'clubs', 'events', 'import_log'})
        self.assertEqual(self.connection.execute('PRAGMA foreign_keys').fetchone()[0], 1)
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 0)
        self.assertEqual(uniclubs_database.get_events(self.connection), [])
        self.assertEqual(uniclubs_database.get_import_log(self.connection), [])

    def test_initialization_preserves_existing_rows(self):
        """Running setup again must retain clubs, events and previous import reports."""
        club_id = self.add_club()
        event_id = uniclubs_database.add_event(
            self.connection, event_record(club_id), now=NOW)
        log_id = uniclubs_database.record_import(self.connection, 'success', 1, now=NOW)
        uniclubs_database.init_db(self.connection)
        self.assertEqual(uniclubs_database.get_events(self.connection)[0]['id'], event_id)
        self.assertEqual(uniclubs_database.get_import_log(self.connection)[0]['id'], log_id)
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 1)

    def test_initialization_preserves_an_unfinished_caller_transaction(self):
        """Refuse nested setup without discarding the caller's pending club insertion."""
        self.connection.execute('''INSERT INTO clubs (external_id, name, source_url)
            VALUES (?, ?, ?)''', ('pending', 'Pending club', CLUB_URL))
        with self.assertRaises(ValueError):
            uniclubs_database.init_db(self.connection)
        self.assertTrue(self.connection.in_transaction)
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 1)
        self.connection.commit()
        uniclubs_database.init_db(self.connection)
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 1)

    def test_same_title_with_distinct_source_ids_remains_distinct(self):
        """Repeated event titles must not replace distinct source events."""
        club_id = self.add_club()
        first = uniclubs_database.add_event(self.connection, event_record(club_id), now=NOW)
        second = uniclubs_database.add_event(
            self.connection, event_record(club_id, external_id='event-2'), now=NOW)
        self.assertNotEqual(first, second)
        rows = uniclubs_database.get_events(self.connection)
        self.assertEqual(len(rows), 2)
        self.assertEqual(rows[0]['title'], rows[1]['title'])

    def test_duplicate_source_ids_fail_without_replacing_data(self):
        """A conflicting club or event insertion must preserve the original rows."""
        club_id = self.add_club()
        event_id = uniclubs_database.add_event(
            self.connection, event_record(club_id), now=NOW)
        with self.assertRaises(sqlite3.IntegrityError):
            uniclubs_database.add_club(self.connection, 'club-1', 'Replacement', CLUB_URL)
        with self.assertRaises(sqlite3.IntegrityError):
            uniclubs_database.add_event(
                self.connection, event_record(club_id, title='Replacement'), now=NOW)
        rows = uniclubs_database.get_events(self.connection)
        self.assertEqual(len(rows), 1)
        self.assertEqual(rows[0]['id'], event_id)
        self.assertEqual(rows[0]['title'], 'Example workshop')
        self.assertEqual(rows[0]['club_name'], 'Example Club')

    def test_missing_club_is_rejected_and_connection_remains_usable(self):
        """An orphan event must fail without preventing a later valid insert."""
        with self.assertRaises(sqlite3.IntegrityError):
            uniclubs_database.add_event(self.connection, event_record(999), now=NOW)
        self.assertEqual(uniclubs_database.get_events(self.connection), [])
        club_id = self.add_club()
        uniclubs_database.add_event(self.connection, event_record(club_id), now=NOW)
        self.assertEqual(len(uniclubs_database.get_events(self.connection)), 1)

    def test_normalized_precision_supports_chronological_joined_reads(self):
        """Mixed input precision must sort by instant and include the correct club."""
        club_id = self.add_club()
        later_id = uniclubs_database.add_event(
            self.connection,
            event_record(club_id, external_id='later', start_utc='2026-11-16T11:00:00.1Z'),
            now=NOW)
        earlier_id = uniclubs_database.add_event(
            self.connection,
            event_record(club_id, external_id='earlier', start_utc='2026-11-16T11:00:00.09Z'),
            now=NOW)
        rows = uniclubs_database.get_events(self.connection)
        self.assertIsInstance(rows[0], sqlite3.Row)
        self.assertEqual([row['id'] for row in rows], [earlier_id, later_id])
        self.assertEqual(rows[0]['start_utc'], '2026-11-16T11:00:00.090000Z')
        self.assertEqual(rows[1]['start_utc'], '2026-11-16T11:00:00.100000Z')
        self.assertEqual(rows[0]['end_utc'], '2026-11-16T12:00:00.000000Z')
        self.assertEqual(rows[0]['club_external_id'], 'club-1')
        self.assertEqual(rows[0]['club_name'], 'Example Club')

    def test_end_must_follow_start_after_time_normalization(self):
        """Reject equal or reversed instants even when their spellings differ."""
        club_id = self.add_club()
        for end in ('2026-11-16T10:59:59Z', '2026-11-16T11:00:00.100000Z'):
            with self.subTest(end=end):
                with self.assertRaises(ValueError):
                    uniclubs_database.add_event(
                        self.connection,
                        event_record(club_id, start_utc='2026-11-16T11:00:00.1Z',
                                     end_utc=end),
                        now=NOW)
        self.assertEqual(uniclubs_database.get_events(self.connection), [])

    def test_optional_end_and_unknown_metadata_are_preserved(self):
        """An unknown duration or membership requirement must not be invented."""
        club_id = self.add_club()
        record = event_record(club_id)
        del record['end_utc']
        uniclubs_database.add_event(self.connection, record, now=NOW)
        row = uniclubs_database.get_events(self.connection)[0]
        self.assertIsNone(row['end_utc'])
        self.assertIsNone(row['requires_membership'])
        self.assertEqual(row['location'], '')
        self.assertEqual(row['event_type'], '')
        self.assertEqual(row['publication_status'], 'unknown')
        self.assertEqual(row['availability_state'], 'unknown')

    def test_seen_times_convert_aware_clocks_and_reject_naive_clocks(self):
        """Observation timestamps must identify UTC instants without guessing a timezone."""
        club_id = self.add_club()
        local_clock = datetime(2026, 11, 15, 18, 0,
                               tzinfo=timezone(timedelta(hours=1)))
        uniclubs_database.add_event(self.connection, event_record(club_id), now=local_clock)
        row = uniclubs_database.get_events(self.connection)[0]
        self.assertEqual(row['first_seen_utc'], SEEN_TIME)
        self.assertEqual(row['last_seen_utc'], SEEN_TIME)
        with self.assertRaises(ValueError):
            uniclubs_database.add_event(
                self.connection, event_record(club_id, external_id='naive'),
                now=datetime(2026, 11, 15, 18, 0))
        self.assertEqual(len(uniclubs_database.get_events(self.connection)), 1)

    def test_publication_and_registration_states_are_independent(self):
        """Published events can have closed registration and require membership."""
        club_id = self.add_club()
        uniclubs_database.add_event(
            self.connection,
            event_record(club_id, publication_status='published',
                         availability_state='sales_closed', requires_membership=True),
            now=NOW)
        row = uniclubs_database.get_events(self.connection)[0]
        self.assertEqual(row['publication_status'], 'published')
        self.assertEqual(row['availability_state'], 'sales_closed')
        self.assertEqual(row['requires_membership'], 1)

    def test_invalid_records_do_not_leave_partial_events(self):
        """Reject missing identifiers, titles and invalid UTC timestamps before saving."""
        club_id = self.add_club()
        candidates = [
            event_record(club_id, external_id=''),
            event_record(club_id, title=' '),
            event_record(club_id, start_utc='not-a-date'),
            event_record(club_id, start_utc='2026-11-16T11:00:00'),
            event_record(club_id, requires_membership='yes'),
        ]
        missing_title = event_record(club_id)
        del missing_title['title']
        candidates.append(missing_title)
        for record in candidates:
            with self.subTest(record=record):
                with self.assertRaises(ValueError):
                    uniclubs_database.add_event(self.connection, record, now=NOW)
        self.assertEqual(uniclubs_database.get_events(self.connection), [])
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 1)

    def test_quoted_text_is_data_instead_of_sql(self):
        """Store apostrophes and SQL-looking event text without executing it."""
        title = "Club's workshop'); DROP TABLE clubs; --"
        club_id = self.add_club()
        uniclubs_database.add_event(
            self.connection, event_record(club_id, title=title), now=NOW)
        self.assertEqual(uniclubs_database.get_events(self.connection)[0]['title'], title)
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 1)

    def test_import_log_orders_reports_and_rejects_invalid_counts(self):
        """Keep success and failure reports while rejecting malformed log entries."""
        first_id = uniclubs_database.record_import(
            self.connection, 'success', 2, message='Two events saved.', now=NOW)
        second_id = uniclubs_database.record_import(
            self.connection, 'error', message='Source unavailable.', now=NOW)
        for invalid_count in (-1, True, 1.5, '2'):
            with self.subTest(event_count=invalid_count):
                with self.assertRaises(ValueError):
                    uniclubs_database.record_import(
                        self.connection, 'success', invalid_count, now=NOW)
        with self.assertRaises(ValueError):
            uniclubs_database.record_import(self.connection, 'pending', now=NOW)
        rows = uniclubs_database.get_import_log(self.connection)
        self.assertEqual([row['id'] for row in rows], [second_id, first_id])
        self.assertEqual(rows[0]['status'], 'error')
        self.assertEqual(rows[0]['event_count'], 0)
        self.assertEqual(rows[0]['message'], 'Source unavailable.')
        self.assertEqual(rows[1]['event_count'], 2)

    def test_saved_catalogue_has_valid_database_and_reference_integrity(self):
        """Representative writes must leave a valid SQLite file structure and references."""
        club_id = self.add_club()
        uniclubs_database.add_event(self.connection, event_record(club_id), now=NOW)
        uniclubs_database.record_import(self.connection, 'success', 1, now=NOW)
        # Course: A07 – SQLite checks verify structural and foreign-key consistency.
        self.assertEqual(self.connection.execute('PRAGMA integrity_check').fetchone()[0], 'ok')
        self.assertEqual(self.connection.execute('PRAGMA foreign_key_check').fetchall(), [])

    def test_direct_sql_rejects_missing_ids_and_fractional_import_counts(self):
        """Table constraints must also reject invalid values when helpers are bypassed."""
        for external_id in (None, '', ' '):
            with self.subTest(external_id=external_id):
                with self.assertRaises(sqlite3.IntegrityError):
                    with self.connection:
                        self.connection.execute(
                            'INSERT INTO clubs (external_id, name, source_url) VALUES (?, ?, ?)',
                            (external_id, 'Example Club', CLUB_URL))
        self.assertEqual(self.connection.execute('SELECT count(*) FROM clubs').fetchone()[0], 0)
        log_id = uniclubs_database.record_import(self.connection, 'success', 1, now=NOW)
        with self.assertRaises(sqlite3.IntegrityError):
            with self.connection:
                self.connection.execute('''INSERT INTO import_log
                    (imported_at_utc, status, event_count, message) VALUES (?, ?, ?, ?)''',
                                        (SEEN_TIME, 'success', 1.5, 'Invalid fractional count.'))
        self.assertEqual([row['id'] for row in uniclubs_database.get_import_log(self.connection)],
                         [log_id])

    def test_direct_event_updates_cannot_bypass_integrity_rules(self):
        """Invalid raw updates must fail and retain the complete original event row."""
        club_id = self.add_club()
        event_id = uniclubs_database.add_event(
            self.connection, event_record(club_id), now=NOW)
        original = dict(uniclubs_database.get_events(self.connection)[0])
        updates = [
            ('UPDATE events SET requires_membership = ? WHERE id = ?', (2, event_id)),
            ('UPDATE events SET end_utc = start_utc WHERE id = ?', (event_id,)),
            ('UPDATE events SET end_utc = ? WHERE id = ?',
             ('2026-11-16T10:00:00.000000Z', event_id)),
            ('UPDATE events SET external_id = ? WHERE id = ?', (None, event_id)),
            ('UPDATE events SET external_id = ? WHERE id = ?', ('', event_id)),
        ]
        for query, params in updates:
            with self.subTest(query=query, params=params):
                with self.assertRaises(sqlite3.IntegrityError):
                    with self.connection:
                        self.connection.execute(query, params)
                self.assertEqual(dict(uniclubs_database.get_events(self.connection)[0]), original)

    def test_existing_weekwise_database_path_is_rejected_before_opening(self):
        """Protect the existing app database without opening or creating its real file."""
        existed_before = config.DB_FILE.exists()
        with patch('uniclubs_database.sqlite3.connect') as connect:
            with self.assertRaises(ValueError):
                uniclubs_database.get_connection(config.DB_FILE)
            connect.assert_not_called()
        self.assertEqual(config.DB_FILE.exists(), existed_before)


if __name__ == '__main__':
    unittest.main()
